'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const prefixSets = Array.from({ length: 11 }, () => new Set());
const suffixSets = Array.from({ length: 11 }, () => new Set());
const substrings = new Set();

for (let i = 0; i < n; i++) {
  const s = input[i + 1];
  const len = s.length;

  if (substrings.has(s)) {
    console.log(s);
    process.exit(0);
  }

  let invalid = false;
  for (let split = 1; split < len; split++) {
    if (
      suffixSets[split].has(s.slice(0, split)) &&
      prefixSets[len - split].has(s.slice(split))
    ) {
      invalid = true;
      break;
    }
  }

  if (invalid) {
    console.log(s);
    process.exit(0);
  }

  for (let l = 1; l <= len; l++) {
    prefixSets[l].add(s.slice(0, l));
    suffixSets[l].add(s.slice(len - l));
    for (let start = 0; start + l <= len; start++) {
      substrings.add(s.slice(start, start + l));
    }
  }
}

console.log('ok');
